cat << 'EOF' > partial_majority_final_digit.py
# name: partial_majority_final_digit
# description: In sets of >=3 examples where all but one example share a final digit (not all), yes-rate for targets with that majority final digit minus yes-rate for other targets; observed > null means the model (which only reacts to a digit shared by ALL examples) under-produces endorsement of near-unanimous final-digit patterns.
def test_statistic(df):
    sets = df["number_set"].unique()
    maj = {}
    for s in sets:
        ex = [int(x) for x in str(s).split(",")]
        if len(ex) < 3:
            continue
        ds = [e % 10 for e in ex]
        for d in set(ds):
            if ds.count(d) == len(ex) - 1:
                maj[s] = d
    m = df["number_set"].map(maj)
    sel = m.notna()
    if sel.sum() == 0:
        return 0.0
    sub = df[sel]
    hit = (sub["target"].astype(int) % 10).values == m[sel].astype(int).values
    r = sub["rating"].values.astype(float)
    if hit.sum() == 0 or (~hit).sum() == 0:
        return 0.0
    return float(r[hit].mean() - r[~hit].mean())
EOF
cat << 'EOF' > singleton_proximity_corr.py
# name: singleton_proximity_corr
# description: Among single-example sets (target != example), Pearson correlation of yes with log(1+|target-example|); observed more negative than null means people use numeric proximity more than the model's one-sided magnitude bounds predict (model under-produces the distance gradient).
def test_statistic(df):
    k = df["number_set"].astype(str).str.count(",") + 1
    sub = df[k == 1]
    x = sub["number_set"].astype(int).values
    t = sub["target"].astype(int).values
    keep = t != x
    d = np.log1p(np.abs(t - x)[keep].astype(float))
    r = sub["rating"].values[keep].astype(float)
    if len(r) < 3 or d.std() == 0 or r.std() == 0:
        return 0.0
    return float(np.corrcoef(d, r)[0, 1])
EOF
cat << 'EOF' > outside_range_distance_corr.py
# name: outside_range_distance_corr
# description: Among multi-example sets, for targets outside [min,max] of the examples, Pearson correlation of yes with distance to the nearest range bound; observed more negative than null means endorsement decays with distance beyond the range more gradually/strongly than the model's step-like bounds produce.
def test_statistic(df):
    sets = df["number_set"].unique()
    mn = {s: min(int(x) for x in str(s).split(",")) for s in sets}
    mx = {s: max(int(x) for x in str(s).split(",")) for s in sets}
    k = df["number_set"].astype(str).str.count(",") + 1
    lo = df["number_set"].map(mn).values
    hi = df["number_set"].map(mx).values
    t = df["target"].astype(int).values
    dist = np.maximum(lo - t, 0) + np.maximum(t - hi, 0)
    sel = (k.values >= 2) & (dist > 0)
    if sel.sum() < 3:
        return 0.0
    d = dist[sel].astype(float)
    r = df["rating"].values[sel].astype(float)
    if d.std() == 0 or r.std() == 0:
        return 0.0
    return float(np.corrcoef(d, r)[0, 1])
EOF
cat << 'EOF' > trial_index_drift.py
# name: trial_index_drift
# description: Pearson correlation between trial_index and yes response across all trials; nonzero observed vs a ~0 null means yes-rate drifts over the session (fatigue/criterion shift) which the stationary model does not produce (sign gives drift direction).
def test_statistic(df):
    t = df["trial_index"].values.astype(float)
    r = df["rating"].values.astype(float)
    if t.std() == 0 or r.std() == 0:
        return 0.0
    return float(np.corrcoef(t, r)[0, 1])
EOF
cat << 'EOF' > sharpness_singleton_vs_large.py
# name: sharpness_singleton_vs_large
# description: Std across targets of per-(set,target) yes-rates, averaged within single-example sets minus averaged within 3-4-example sets; observed > null means singleton generalization is more graded/sharp relative to large sets than the model's single slope across set sizes produces (i.e. model under-differentiates targets for singletons, or over-differentiates for large sets if lower).
def test_statistic(df):
    k = df["number_set"].astype(str).str.count(",") + 1
    cell = df.assign(k=k).groupby(["number_set", "target"]).agg(r=("rating", "mean"), k=("k", "first")).reset_index()
    sd = cell.groupby("number_set").agg(s=("r", "std"), k=("k", "first")).dropna()
    a = sd.loc[sd["k"] == 1, "s"]
    b = sd.loc[sd["k"] >= 3, "s"]
    if len(a) == 0 or len(b) == 0:
        return 0.0
    return float(a.mean() - b.mean())
EOF
cat << 'EOF' > shared_decade_bonus.py
# name: shared_decade_bonus
# description: Among multi-example sets, yes-rate for targets whose tens digit equals some example's tens digit minus yes-rate for targets that share no example's tens digit (targets that are examples excluded); observed > null means the model under-produces endorsement driven by same-decade similarity, which it has no feature for.
def test_statistic(df):
    sets = df["number_set"].unique()
    tens = {}
    for s in sets:
        ex = [int(x) for x in str(s).split(",")]
        if len(ex) >= 2:
            tens[s] = set(e // 10 for e in ex)
    sub = df[df["number_set"].isin(list(tens.keys()))]
    if len(sub) == 0:
        return 0.0
    t = sub["target"].astype(int).values
    keys = sub["number_set"].values
    # vectorised via a lookup table: set index x decade
    idx = {s: i for i, s in enumerate(tens)}
    tab = np.zeros((len(idx), 11), dtype=bool)
    for s, i in idx.items():
        for d in tens[s]:
            tab[i, d] = True
    si = np.array([idx[s] for s in pd.unique(keys)])
    codes = pd.Series(keys).map(idx).values
    hit = tab[codes, t // 10]
    r = sub["rating"].values.astype(float)
    if hit.sum() == 0 or (~hit).sum() == 0:
        return 0.0
    return float(r[hit].mean() - r[~hit].mean())
EOF
cat << 'EOF' > prime_odd_targets_odd_sets.py
# name: prime_odd_targets_odd_sets
# description: In sets whose examples are all odd but not all prime, among odd targets, yes-rate for prime targets minus non-prime odd targets; observed > null means people favour prime-looking targets beyond what the model (prime family only active when all examples are prime) produces.
def test_statistic(df):
    primes = {n for n in range(2, 101) if all(n % d for d in range(2, int(n ** 0.5) + 1))}
    ok = {}
    for s in df["number_set"].unique():
        ex = [int(x) for x in str(s).split(",")]
        ok[s] = all(e % 2 == 1 for e in ex) and not all(e in primes for e in ex)
    t = df["target"].astype(int)
    sel = df["number_set"].map(ok).astype(bool).values & (t.values % 2 == 1)
    if sel.sum() == 0:
        return 0.0
    tp = t.values[sel]
    isp = np.isin(tp, list(primes))
    r = df["rating"].values[sel].astype(float)
    if isp.sum() == 0 or (~isp).sum() == 0:
        return 0.0
    return float(r[isp].mean() - r[~isp].mean())
EOF
cat << 'EOF' > last_vs_first_example_digit.py
# name: last_vs_first_example_digit
# description: In multi-example sets whose first and last shown examples have different final digits, yes-rate for targets sharing the LAST example's final digit minus yes-rate for targets sharing the FIRST example's final digit; nonzero observed vs null means presentation order (recency/primacy) matters, which the order-blind model cannot produce (positive = recency).
def test_statistic(df):
    fl = {}
    for s in df["number_set"].unique():
        ex = [int(x) for x in str(s).split(",")]
        if len(ex) >= 2 and ex[0] % 10 != ex[-1] % 10:
            fl[s] = (ex[0] % 10, ex[-1] % 10)
    sub = df[df["number_set"].isin(list(fl.keys()))]
    if len(sub) == 0:
        return 0.0
    f = sub["number_set"].map(lambda s: fl[s][0]).values
    l = sub["number_set"].map(lambda s: fl[s][1]).values
    td = sub["target"].astype(int).values % 10
    r = sub["rating"].values.astype(float)
    hl = td == l
    hf = td == f
    if hl.sum() == 0 or hf.sum() == 0:
        return 0.0
    return float(r[hl].mean() - r[hf].mean())
EOF
